sys_script_include.script:
var ContrastAppListIntegrationJsonSAST = Class.create();
ContrastAppListIntegrationJsonSAST.prototype = Object.extendsObject(sn_vul.ApplicationVulnerabilityIntegrationBase, {

    UTIL: new x_ntsi_contrast_ap.ContrastUtilBase(),

    retrieveData: function() {
        var resp = new x_ntsi_contrast_ap.ContrastUtilBase().triggerAPISAST(this.IMPLEMENTATION); //getApplicationListForValidation
        var responseBody = resp.getBody();

        if (resp.getStatusCode() == 200) {
            var appURL = new x_ntsi_contrast_ap.ContrastUtilBase().getApiURLDetails();

            try {

                var contentjson = JSON.parse(responseBody);
                var responseContent = contentjson.content;
                var arr = [];
                for (var a in responseContent) {
                    var pageNum = 0;

                        var vulresp = new x_ntsi_contrast_ap.ContrastUtilBase().getSASTVulnerabilities(this.IMPLEMENTATION, responseContent[a].id, pageNum);
                        var rtnresp = JSON.parse(vulresp.getBody());
                        var rtnValue = vulresp.getBody();
                        if (rtnValue == null) {
                            break;
                        }
                        if (rtnValue.indexOf('numberOfElements') == -1) {
                            break;
                        }

                        if (rtnresp.numberOfElements == undefined || rtnresp.numberOfElements == null || rtnresp.numberOfElements == "" || rtnresp.numberOfElements == "null" || rtnresp.numberOfElements == 0) {
                            pageNum = 0;
                            break;
                        } else {
                            if (vulresp.getStatusCode() == 200) {
                                var vul = JSON.parse(vulresp.getBody());
                                var trace = vul.content;
                                for (var a1 in trace) {
                                    var obj = trace[a1];
                                    delete obj.locations;
                                    delete obj.codeFlows;
                                    obj.source_link = "https://" + appURL + "/Contrast/api/sast/organizations/" + trace[a1].organizationId + "/projects/" + trace[a1].projectId + "/results/" + trace[a1].id;
                                    obj.name = responseContent[a].name;
                                    if (trace[a1].status != "REMEDIATED") {
                                        arr.push(obj);
                                    }
                                }
                            }
                            pageNum++;
                        }


                    //Generate object for Application 
                    var appObj = {
                        source_app_id: responseContent[a].id + "",
                        app_name: responseContent[a].name + "",
                        description: responseContent[a].name + "",
                        source_app_guid: responseContent[a].id + "",
                    };

                    var result = this.AVR_API.createOrUpdateApp(appObj);

                }
                arr.join();
                var content = {
                    "content": arr
                };

                //Generate Attachment with Response payload to trigger data source
                var attachmentGr = new GlideSysAttachment();
                var fileName = this.integrationGr.name + "_" + new GlideDateTime().toString() + ".json";
                var sysId = attachmentGr.write(this.integrationProcessGr, fileName, "json", JSON.stringify(content));
                var obj1 = {
                    contents: sysId,
                    contentType: "sys_attachment",
                    extension: "json"
                };

                return obj1;
            } catch (e) {
                gs.error("Failed to parse JSON: " + e.message);
                // Optionally handle the error or take fallback action
            }
        } else {
            gs.error("API Failed with status code: " + resp.getStatusCode());
            return null;
        }
    },

    shouldRetry: function(process) {
        return true;
    },



    type: 'ContrastAppListIntegrationJsonSAST'
});
